  IEnumerator FoodHands(Group g){int original=loop.Consumables.PreferredHand;try{foreach(int preferred in new[]{2,1}){loop.RestartRound();Neutral();ParkProbeFoods();FreeActualSlot(g);loop.Consumables.PreferredHand=preferred;int physical=preferred==2?1:2;string id="posttest/food/preferred"+preferred;Vector3 at=(physical==1?loop.Rig.Left:loop.Rig.Right).position;Need(loop.Consumables.Spawn(id,"banana",at),"Finite actual banana at reaching hand");ItemGripFrame(physical,0);ItemGripFrame(physical,1);Note(g,ItemState());Need(lastItemObjective.Id==id,"Actual requested food wins physical grip selection");Need(loop.Consumables.HeldId==id&&loop.Consumables.HeldHand==preferred,"Physical opposite-hand grip equips configured weapon hand");Need(!loop.Gameplay.HasWeapon,"Existing Root custody holsters gun for food");yield return null;Note(g,"Physical hand"+physical+" -> configured hand"+preferred+"; finite banana owned and actual gun holstered");}
    loop.RestartRound();Neutral();ParkProbeFoods();FreeActualSlot(g);loop.Consumables.PreferredHand=2;string stored="posttest/food/untracked-right";Need(loop.Consumables.Spawn(stored,"soda",loop.Rig.Left.position),"Finite real soda");string previousGuns=String.Join(",",loop.Gameplay.OwnedWeaponActionIds);ItemGripFrame(1,0,true,false);ItemGripFrame(1,1,true,false);var item=loop.Consumables.InspectItem(stored);Note(g,ItemState()+" storedOwner="+(item==null?"missing":item.Owner??"world"));Need(lastItemObjective.Id==stored,"Actual untracked-case soda wins physical grip selection");Need(item!=null&&item.Owner!=null&&loop.Consumables.HeldId==null,"Unavailable weapon hand stores collected item, never silently equips offhand");Need(String.Join(",",loop.Gameplay.OwnedWeaponActionIds)==previousGuns,"Refused untracked equip preserves existing owned gun identities");Note(g,"Right untracked: actual collected soda stored; no offhand fallback or gun loss");
   }finally{loop.Consumables.PreferredHand=original;loop.Rig.SmokeTrackedHands(new HandSample{Tracked=true},new HandSample{Tracked=true});}yield break;}
  IEnumerator Backpacks(Group g){ParkProbeFoods();loop.Gameplay.HolsterCurrent();loop.Supplies.SetWorldVisible(true);Need(loop.InventoryCapacity==3,"Actual fresh capacity3");string prefix="posttest/one-bag/";for(int i=0;i<4;i++)Need(loop.Supplies.Spawn(prefix+i,"backpack",loop.Rig.Right.position+Vector3.right*(.09f*i),1),"Real separate backpack "+i);int collected=0;Action<string,string,int> count=delegate(string id,string family,int amount){if(id.StartsWith(prefix,StringComparison.Ordinal)){Need(family=="backpack"&&amount==1,"One actual slot event");collected++;}};loop.Supplies.Collected+=count;
   try{for(int press=0;press<3;press++){ItemGripFrame(2,0);ItemGripFrame(2,1);Note(g,ItemState()+" collectedEvents="+collected+" freshPress="+press);Need(lastItemObjective.Kind==Ashfall.Integration.Playable.Input.R23GripObjectiveKind.Supply&&lastItemObjective.Id.StartsWith(prefix,StringComparison.Ordinal),"Actual probe backpack wins this fresh grip");Need(loop.InventoryCapacity==4+press&&collected==press+1,"One fresh physical grip grants exactly one slot");for(int held=0;held<20;held++)ItemGripFrame(2,1);Need(loop.InventoryCapacity==4+press&&collected==press+1,"Held grip cannot cascade across nearby backpacks");yield return null;}ItemGripFrame(2,0);ItemGripFrame(2,1);Need(loop.InventoryCapacity==6&&collected==3,"Full source capacity refuses fourth backpack");int visibleUncollected=0;for(int i=0;i<4;i++){R24SupplyItem item;Need(loop.Supplies.TryReadItem(prefix+i,out item),"Existing finite bag record");if(!item.Collected)visibleUncollected++;}Need(visibleUncollected==1,"Fourth backpack retained rather than consumed");Note(g,"Actual Root grip route3->4->5->6,60held frames no extra grants, fourth item retained at capacity");}finally{loop.Supplies.Collected-=count;}yield break;}
  IEnumerator SupportGloves(Group g){
   var gameplay=loop.Gameplay;bool toggle=(bool)Read(gameplay,"requestedGripToggle");gameplay.SetGripToggle(false);
   try{foreach(int primary in new[]{1,0}){
    Neutral();Need(gameplay.EquipOwned(ActualOwnedRifle(),primary),"Actual carried source rifle in physical hand"+primary);
    Transform rawPrimary=primary==0?loop.Rig.Left:loop.Rig.Right,rawSupport=primary==0?loop.Rig.Right:loop.Rig.Left;
    Transform root=(Transform)Read(gameplay,"weapon");var models=(List<Transform>)Read(gameplay,"weaponModels");var model=models[(int)Read(gameplay,"selectedWeapon")];
    float scale=(float)gameplay.GetType().GetProperty("LogicalReloadScale",Flags).GetValue(gameplay,null);
    for(int pose=0;pose<3;pose++){
     rawPrimary.rotation=Quaternion.Euler(13+pose*7,31+pose*29,-11+pose*4);rawPrimary.position+=new Vector3(.03f,.01f,-.02f);
     rawSupport.position=root.TransformPoint(new Vector3(0,-.025f,.36f)*scale)+new Vector3(.018f,.012f,0);rawSupport.rotation=Quaternion.Euler(74,19,-48);
     var input=new R23HandsInputFrame{LeftTracked=true,RightTracked=true};gameplay.TickInput(.02f,input);
     if(primary==1)input.LeftGrip=1;else input.RightGrip=1;
     Vector3 primaryBefore=rawPrimary.position,supportBefore=rawSupport.position;Quaternion pr=rawPrimary.rotation,sr=rawSupport.rotation;
     gameplay.TickInput(.02f,input);gameplay.RefreshFeedbackPresentation();
     var round=(R23RoundState)Read(gameplay,"round");Need(round.ActiveSnapshot.Supported,"Real owner support acquired: "+gameplay.ActiveWeaponId);
     Vector3 point;Quaternion rotation;Need(gameplay.TryReadHandArtPose(1-primary,out point,out rotation),"Actual support art visible");
     Need(Vector3.Distance(point,model.TransformPoint(new Vector3(0,-.025f,.36f)))<.0001f,"Glove follows actual scaled/recoiling model foregrip");
     float mirror=primary==1?1:-1;var fingers=new Vector3(-.018913137f*mirror,.166124628f,.985923375f);
     Need(Vector3.Distance(rotation*fingers,model.forward)<.0001f,"Support fingers follow visible bore");
     Need(rawPrimary.position==primaryBefore&&rawSupport.position==supportBefore&&Quaternion.Angle(rawPrimary.rotation,pr)<.001f&&Quaternion.Angle(rawSupport.rotation,sr)<.001f,"Art update leaves both tracked controllers unchanged");
     input.LeftGrip=input.RightGrip=0;gameplay.TickInput(.02f,input);gameplay.RefreshFeedbackPresentation();
     Need(!round.ActiveSnapshot.Supported,"Real grip release clears support");Need(gameplay.TryReadHandArtPose(1-primary,out point,out rotation),"Released glove visible");
     Need(Vector3.Distance(point,rawSupport.position)<.0001f&&Quaternion.Angle(rotation,rawSupport.rotation*R23TrackedGripPose.GloveLocalRotation(1-primary))<.01f,"Released art returns to tracked rest calibration");
     Note(g,"primary="+primary+" pose="+pose+" actual acquisition/model contact/release/tracked transforms preserved");yield return null;
    }
   }}finally{gameplay.SetGripToggle(toggle);gameplay.HolsterCurrent();}yield break;
  }
